import fs from 'fs';

// regexps generated by claude sonnet 5.5 medium
const BLOCK_PATTERN = /\bvar\s*\(([\s\S]*?)^\)/m;
const DLL_PATTERN = /NewLazy(?:System)?DLL\("([^"]+)"\)/;
const FUNC_PATTERN = /NewProc\("([^"]+)"\)/g;
const README_FUNC_PATTERN = /^#+[ \t]*functions[ \t]*$/im;

const allFuncs = [];

const files = fs.readdirSync('.');
files.forEach((file) => {
    if (!file.endsWith('.go')) {
        return;
    }

    const fileData = fs.readFileSync(file, 'utf8');

    const block = BLOCK_PATTERN.exec(fileData);
    if (!block) return;

    const dll = DLL_PATTERN.exec(block[1]);
    if (!dll) return;

    block[1].matchAll(FUNC_PATTERN).forEach((match) => {
        allFuncs.push(`${dll[1]}!${match[1]}`)
    });
});

const formatted = allFuncs.map((line, index) => {
    return `${index + 1}. \`${line}\``;
}).join('\n');

const readme = fs.readFileSync('README.md', 'utf-8');
const header = README_FUNC_PATTERN.exec(readme);
const head = readme.slice(0, header.index + header[0].length);

fs.writeFileSync('README.md', `${head}\n${formatted}\n`);

console.log('readme updated!');
